package net.officefloor.hq.app.paste;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.claim.ClaimRequest;
import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.PersonRequest;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Splits the paste into lines (blank lines skipped) and checks each by the claim form's rules (a
 * note ending {@code " #<reference>"} gives the claim's reference); the
 * first line that fails refuses the whole paste. A paste with no lines is refused too.
 */
public class ValidatePaste {
    public void validate(@RequestBody PasteRequest request, Out<PasteLines> linesOut) throws InvalidClaimException {
        String text = request == null || request.text() == null ? "" : request.text();
        List<PasteLine> lines = new ArrayList<>();
        int number = 0;
        for (String raw : text.split("\\r?\\n|\\r")) {
            number++;
            if (raw.isBlank()) continue;
            String[] fields = raw.split(",", 4);
            if (fields.length < 2) throw new InvalidClaimException("Line " + number + ": name,amount,date,note");
            String name;
            try {
                name = PersonRequest.checkName(fields[0]);
            } catch (InvalidPersonException e) {
                throw new InvalidClaimException("Line " + number + ": " + e.getMessage());
            }
            String date = fields.length > 2 ? fields[2] : "";
            String note = fields.length > 3 ? fields[3].trim() : "";
            // A note ending " #<reference>" gives the claim's reference: that part is not the note's.
            String ref = "";
            int hash = note.lastIndexOf(" #");
            if (hash >= 0) {
                ref = note.substring(hash + 2);
                note = note.substring(0, hash);
            }
            try {
                ClaimInput claim = ClaimInput.from(new ClaimRequest(fields[1], date, note, "", ref));
                lines.add(new PasteLine(name, claim));
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Line " + number + ": " + e.getMessage());
            }
        }
        if (lines.isEmpty()) throw new InvalidClaimException("Paste at least one line of name,amount,date,note");
        linesOut.set(new PasteLines(lines));
    }
}
src/main/resources/officefloor/rest/api/sheets/{sheetId}/claims/paste.POST.yml
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useUser } from '../session/session';
import { peopleKey } from '../people/people';
import { claimsKey } from '../claims/claims';

type Result = { added: number };

// The paste box: lines of name,amount,date,note (the date may be blank for the sheet's entry date while set, else its today, the
// note may be absent and may hold commas) each add a DRAFT claim, in order, for the named person on
// the sheet. The server checks every line by the claim form's rules first: one bad line refuses the
// whole paste and adds nothing. The box shows how many were added; the count is cleared while it runs.
function PasteClaims({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const [result, setResult] = useState<Result | null>(null);
  const [error, setError] = useState('');
  const [user] = useUser();

  const once = useOnce();
  const paste = useMutation({
    mutationFn: (body: { text: string }) =>
      postJson<Result>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/paste`, body, user),
    onSuccess: (r) => {
      setResult(r);
      setText('');
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: () => setError('Those claims could not be added: check every line.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setResult(null);
    setError('');
    if (text.trim() === '') {
      setError('Paste at least one line of name,amount,date,note.');
      return;
    }
    once((done) => paste.mutate({ text }, { onSettled: done }));
  };

  return (
    <section data-testid="paste-box">
      <form onSubmit={submit}>
        <label>
          Paste claims (name,amount,date,note){' '}
          <textarea
            data-testid="paste-claims"
            rows={4}
            value={text}
            onChange={(e) => {
              setText(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="paste-submit" disabled={paste.isPending}>
          Add pasted claims
        </button>
        {result !== null && (
          <>
            {' '}Added <span data-testid="paste-added">{result.added}</span>
          </>
        )}
        {error && (
          <p role="alert" data-testid="paste-error">
            {error}
          </p>
        )}
      </form>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 1.5, Component: PasteClaims });

