# Edit a claim's amount, date, note and reference. Validate first so a bad amount or date is a 400, not a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: locked
# A claim whose editor another user has open is a 409 and writes nothing.
locked:
  class: net.officefloor.hq.app.claim.CheckClaimLock
  govern: [ transaction ]
  next: closed
# A claim due by a date inside a closed period is a 409 and writes nothing. An edit keeps its due-by,
# so it cannot move it into one.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaim
  govern: [ transaction ]
  next: ref
# A reference another claim on the sheet has (regardless of case) is a 400 and writes nothing.
ref:
  class: net.officefloor.hq.app.claim.CheckClaimRef
  govern: [ transaction ]
  next: correction
# A correction (a negative amount) must name a settled claim of the same person: else a 400.
correction:
  class: net.officefloor.hq.app.claim.CheckCorrection
  govern: [ transaction ]
  next: retired
# Nor may an edit date it after its person's retirement date.
retired:
  class: net.officefloor.hq.app.person.CheckClaimRetired
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: release
# A saved edit closes the claim's editor: its lock is released.
release:
  class: net.officefloor.hq.app.claim.ReleaseClaimLock
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimEdited
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]

