778-  // A paste that only updates DRAFTs in place adds no row: the count it shows is the
779-  // result, judged against the value before the click as countAfter judges it.
780-  const cell = page.getByTestId('paste-added');
781-  const before = await claimRows(page).count();
782-  const was = (await cell.count()) > 0 ? await shown(cell) : '';
783-  await page.getByTestId('paste-claims').fill(text);
784-  await page.getByTestId('paste-submit').click();
785-  let cleared = false;
786-  const counted = async () => {
787-    if ((await cell.count()) === 0) return false;
788-    const now = await shown(cell);
789-    if (now === '') { cleared = true; return false; }
790-    return now !== was || was === '' || cleared;
791-  };
792-  const ok = await until(page, async () => (await counted()) || (await claimRows(page).count()) > before,
793-    page.getByTestId('paste-error'), 'paste claims');
794-  return ok ? Number(await shown(cell)) : null;
795-}
