package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Applies an edit to a draft, recording the signed-in user as the one who last edited it. A draft with
 * lines keeps their total as its amount: an edit typing another amount is refused.
 */
public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Sheet sheet, @Val Claim claim, ClaimLineRepository lines,
            HttpServletRequest request) throws InvalidClaimStatusException, InvalidClaimException {
        claim.checkEditable();
        BigDecimal total = lines.total(claim);
        if (total != null && total.compareTo(input.amount()) != 0) {
            throw new InvalidClaimException("A claim with lines takes their total as its amount");
        }
        claim.setAmount(input.amount());
        claim.setDate(input.date() == null ? sheet.today() : input.date());
        claim.setNote(input.note());
        claim.setCorrects(input.corrects());
        claim.setRef(input.ref());
        claim.setTags(input.tags());
        claim.setEditedBy(Audit.user(request));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the saved claim. Runs after every rule has passed, so a refused change writes nothing. */
public class AuditClaimEdited {
    public void audit(@Val Sheet sheet, @Val Claim claim, PersonRepository people,
            HttpServletRequest request, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_EDITED", sheet, Audit.user(request),
                people.find(sheet.id(), claim.getPersonId()), claim));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/**
 * Records the saved claim (with its reference, then its tags, at the end when it has them), then LATE_ENTRY naming it when it was added while its period was
 * soft-closed. Runs after every rule has passed, so a refused change writes nothing.
 */
public class AuditClaimAdded {
    public void audit(@Val Sheet sheet, @Val Person person, @Val Claim claim,
            HttpServletRequest request, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_ADDED", sheet, Audit.user(request), person, claim)
                + (claim.getRef() == null ? "" : " ref=" + claim.getRef())
                + (claim.getTags() == null ? "" : " tags=" + claim.getTags()));
        if (claim.isLateEntry()) audit.record(ClaimAudit.line("LATE_ENTRY", sheet, Audit.user(request), person, claim));
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Refuses an edit of a claim whose editor another user has open, before anything is written. */
public class CheckClaimLock {
    public void check(@Val Sheet sheet, @Val Claim claim, ClaimRepository repository,
            HttpServletRequest request) throws ClaimLockedException {
        if (repository.lockedByOther(claim, Audit.user(request), sheet.today())) {
            throw new ClaimLockedException(String.valueOf(claim.getId()));
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Deletes the claim: only a DRAFT may be deleted. A DELETED claim counts nowhere and cannot be edited, opened or voided. */
public class DeleteClaim {
    public void apply(@Val Claim claim) throws InvalidClaimStatusException {
        claim.moveTo(ClaimStatus.DELETED);
    }
}
